/* Lot 100: color and background-color keyframes and @starting-style transitions (generated by scripts/lot100_colorgen.py; expectations from scripts/lot100_colormodel.py). */
#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "wf_sitecss.h"

static wf_site_t g_d;
static char g_html[6144];
static char g_o[1024];

static void prep(const char *css, int ms) {
    wf_site_set_time(ms);
    snprintf(g_html, sizeof(g_html), "<html><head><style>%s</style></head><body>"
             "<div id=o><p id=i>i</p></div><p id=q>q</p></body></html>", css);
    TEST_ASSERT_EQUAL(0, wf_site_prepare_ext(&g_d, g_html, (int)strlen(g_html), 640, 480, 0, 0));
    wf_site_set_time(0);
}

static const char *style_of(const char *id) {
    int i;
    g_o[0] = 0;
    for (i = 0; i < g_d.nnodes; i++)
        if (!strcmp(g_d.node[i].id, id)) wf_site_style_attr(&g_d, g_d.node[i].start, g_o, (int)sizeof(g_o));
    return g_o;
}

static void test_l100_anim_0(void) {
    prep("@starting-style { #o { color: #cb9 } } #o { transition-property: none; transition-duration: 1s, 0s; transition-timing-function: linear, ease }", 498);
    TEST_ASSERT_EQUAL_STRING("", style_of("o"));
    TEST_ASSERT_EQUAL_STRING("", style_of("i"));
    TEST_ASSERT_EQUAL(0, g_d.col_animated);
    TEST_ASSERT_EQUAL(0, g_d.col_transitioned);
    TEST_ASSERT_EQUAL(0, g_d.prop_composed);
    prep("@starting-style { #o { color: #788 } } #o { transition: background-color 1s allow-discrete }", 634);
    TEST_ASSERT_EQUAL_STRING("", style_of("o"));
    TEST_ASSERT_EQUAL_STRING("", style_of("i"));
    TEST_ASSERT_EQUAL(0, g_d.col_animated);
    TEST_ASSERT_EQUAL(0, g_d.col_transitioned);
    TEST_ASSERT_EQUAL(0, g_d.prop_composed);
    prep("@keyframes k { 50% { background-color: var(--c) } } #o { color: rgb(222 235 46 / 120%); background-color: hsl(-89.4266deg 50% 0%); animation-name: k; animation-duration: 500ms, 1s; animation-timing-function: linear }", 1500);
    TEST_ASSERT_EQUAL_STRING(" style=\"color:#deeb2e;background-color:#000000\"", style_of("o"));
    TEST_ASSERT_EQUAL_STRING("", style_of("i"));
    TEST_ASSERT_EQUAL(0, g_d.col_animated);
    TEST_ASSERT_EQUAL(0, g_d.col_transitioned);
    TEST_ASSERT_EQUAL(0, g_d.prop_composed);
    prep("@keyframes k { 33.33% { background-color: currentcolor; color: hwb(1turn 100% 0%) } } @keyframes j { 0% { color: var(--c); background-color: rgb(a, 2, 3) } 60% { background-color: color-mix(in  srgb,color-mix(in  srgb , rgb(126 230 32%) , #efbe4f),hsl(0.8turn, 76%, 81.7%)); color: hwb(-60deg 100% 100%) } } #o { color: hwb(300.5deg 50% 89.44% /0) !important; animation: k 2000ms linear, none 500ms steps(4) }", 1307);
    TEST_ASSERT_EQUAL_STRING(" style=\"color:#5b5b5b00\"", style_of("o"));
    TEST_ASSERT_EQUAL_STRING("", style_of("i"));
    TEST_ASSERT_EQUAL(1, g_d.col_animated);
    TEST_ASSERT_EQUAL(0, g_d.col_transitioned);
    TEST_ASSERT_EQUAL(0, g_d.prop_composed);
}

